CREATE FUNCTION economy_validate_money() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE target_entity uuid; reward_value numeric;
BEGIN
  target_entity := CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;
  SELECT v.value_decimal INTO reward_value FROM entity_parameter_values v WHERE v.entity_id=target_entity AND v.parameter_id='715eb3fa-220a-5307-a746-7bc087bc9543';
  IF reward_value IS NOT NULL AND (reward_value<>trunc(reward_value) OR reward_value<0 OR reward_value>9223372036854775807) THEN RAISE EXCEPTION 'Reward gold must be an exact nonnegative milli integer' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER economy_integer_gold AFTER INSERT OR UPDATE OR DELETE ON entity_parameter_values DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION economy_validate_money();
REVOKE ALL ON FUNCTION economy_validate_money() FROM PUBLIC;
